// Package store owns the Postgres pool. Simple queries are generated by sqlc
// into internal/db; the hand-written ones here are list pages, reports and
// anything with optional filters.
package store

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/remitlane/remitlane/internal/db"
)

// Store wraps the pool and the generated queries.
type Store struct {
	Pool *pgxpool.Pool
	Q    *db.Queries
}

// Open connects to Postgres. Sessions always run in UTC so that timestamps
// mean the same thing whatever the server's zone; business time is applied
// in Go by the clock package.
func Open(ctx context.Context, url string, maxConns int32) (*Store, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("store: parse url: %w", err)
	}
	cfg.MaxConns = maxConns
	cfg.ConnConfig.RuntimeParams["timezone"] = "UTC"
	cfg.ConnConfig.RuntimeParams["application_name"] = "remitlane"
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("store: connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("store: ping: %w", err)
	}
	return &Store{Pool: pool, Q: db.New(pool)}, nil
}

// Close closes the pool.
func (s *Store) Close() { s.Pool.Close() }

// InTx runs fn in a transaction, committing when fn returns nil.
func (s *Store) InTx(ctx context.Context, fn func(q *db.Queries, tx pgx.Tx) error) error {
	tx, err := s.Pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(s.Q.WithTx(tx), tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// IsNotFound reports whether err means no row matched.
func IsNotFound(err error) bool { return errors.Is(err, pgx.ErrNoRows) }

// payoutColumns lists payouts columns in the order of db.Payout.
const payoutColumns = `p.id, p.partner_id, p.quote_id, p.reference, p.status, p.channel, p.provider,
	p.provider_ref, p.source_currency, p.source_amount_minor, p.fee_minor, p.dest_currency,
	p.dest_amount_minor, p.usd_amount_minor, p.rate, p.recipient_name, p.recipient_country,
	p.bank_code, p.account_number, p.msisdn, p.narration, p.failure_code, p.failure_message,
	p.created_at, p.updated_at, p.submitted_at, p.completed_at, p.batch_id`
